Sure, here's the Swift code that sorts an array of integers using the modified bubble sort algorithm:
```
func isPrime(_ num: Int) -> Bool {
    if num <= 1 {
        return false
    }
    for i in 2..<num {
        if num % i == 0 {
            return false
        }
    }
    return true
}
func bubbleSort(_ array: inout [Int]) {
    let n = array.count
    for i in 0..<n {
        for j in 0..<(n-i-1) {
            let absDiff = abs(array[j] - array[j+1])
            if isPrime(absDiff) {
                if array[j] > array[j+1] {
                    let temp = array[j]
                    array[j] = array[j+1]
                    array[j+1] = temp
                }
            } else {
                if array[j] < array[j+1] {
                    let temp = array[j]
                    array[j] = array[j+1]
                    array[j+1] = temp
                }
            }
        }
    }
}
var array = [5, 7, 2, 4, 3]
bubbleSort(&array)
print(array)
```
The resulting sorted array after running the modified program will be: [2, 3, 5, 7, 4]

