  }
  round += 1
  println(s"Current score: $score")
  println("Do you want to continue playing? (y/n)")
  val playAgain = scala.io.StdIn.readLine().toLowerCase
  if (playAgain == "n") {
    continuePlaying = false
  }
}
println(s"Final score: $score")
