import CoreLocation
class ViewController: UIViewController, CLLocationManagerDelegate {
    let locationManager = CLLocationManager()
    override func viewDidLoad() {
        super.viewDidLoad()
        // Request permission to access location
        locationManager.requestWhenInUseAuthorization()
        // Set up location manager
        locationManager.delegate = self
        locationManager.desiredAccuracy = kCLLocationAccuracyBest
    }
    // CLLocationManagerDelegate method called when location is updated
    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard let userLocation = locations.last else { return }
        // Create a second location for testing purposes
        let testLocation = CLLocation(latitude: 37.7749, longitude: -122.4194)
        // Calculate distance between user location and test location
        let distance = self.distance(from: userLocation, to: testLocation)
        print("Distance between user location and test location: \(distance) meters")
    }
    // Function to calculate distance between two locations using Haversine formula
    func distance(from: CLLocation, to: CLLocation) -> CLLocationDistance {
        // Same code as before
        let earthRadius = 6_371_000.0 // in meters
        let lat1 = from.coordinate.latitude
        let lat2 = to.coordinate.latitude
        let lon1 = from.coordinate.longitude
        let lon2 = to.coordinate.longitude
        let dLat = (lat2 - lat1) * .pi / 180.0
        let dLon = (lon2 - lon1) * .pi / 180.0
        let a = sin(dLat/2) * sin(dLat/2) + cos(lat1 * .pi / 180.0) * cos(lat2 * .pi / 180.0) * sin(dLon/2) * sin(dLon/2)
        let c = 2 * atan2(sqrt(a), sqrt(1-a))
        let distance = earthRadius * c
        return distance
    }
}
