```swift
// Define the symbol-to-letter correspondence dictionary
let symbolToLetter: [Character: Character] = [
    "1": "A",
    "2": "B",
    "3": "C",
    "#": "D",
    "@": "E",
    "&": "F"
]
// Define the function to decode the transmission message
func decodeTransmissionMessage(_ message: [[Character]]) -> String {
    var decodedMessage = ""

    // Decode each symbol in the message
    for row in message {
        var decodedRow = ""
        for symbol in row {
            if let letter = symbolToLetter[symbol] {
                decodedRow.append(letter)
            }
        }
        decodedMessage.append(decodedRow)
    }

    return decodedMessage
}
// Example usage
let transmissionMessage = [["1", "#", "2", "&", "@", "3"]]
let decodedMessage = decodeTransmissionMessage(transmissionMessage)
print(decodedMessage) // Output: "ADBECF"
```
