function [customer_names, customer_emails] = retrieve_customer_info()
    % Connect to the database
    conn = database('database_name', 'username', 'password');

    % Construct the SQL query to retrieve the customer names and emails
    sql_query = "SELECT customer_name, customer_email FROM sales WHERE purchase_date >= '2020-01-01' AND purchase_date <= '2020-12-31'";

