            new Dog { Breed = "Jack Russell Terrier", Weight = 15, ActivityLevel = 4 },
            new Dog { Breed = "Dalmatian", Weight = 50, ActivityLevel = 3 },
        };
        Console.WriteLine("Recommended exercise time for each dog:");
        foreach (Dog dog in dogs) {
            double exerciseTime = dog.CalculateExerciseTime();
            Console.WriteLine($"{dog.Breed}: {exerciseTime} minutes");
        }
    }
}
```
