How can I retrieve the largest ocean on Earth in terms of both volume and surface area, taking into account the varying definitions of oceanic basins and the complex tectonic and hydrological factors that affect their boundaries and properties, using PHP code?
Here's a possible solution:
<?php
$curl = curl_init();
curl_setopt_array($curl, array(
  CURLOPT_URL => "https://en.wikipedia.org/w/api.php?action=query&format=json&prop=extracts&exintro&explaintext&titles=Ocean&redirects=1&formatversion=2",
  CURLOPT_RETURNTRANSFER => true,
  CURLOPT_ENCODING => "",
  CURLOPT_MAXREDIRS => 10,
  CURLOPT_TIMEOUT => 30,
  CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
  CURLOPT_CUSTOMREQUEST => "GET",
));
$response = curl_exec($curl);
$err = curl_error($curl);
curl_close($curl);
if ($err) {
  echo "cURL Error #:" . $err;
} else {
  $data = json_decode($response, true);
  $extract = $data['query']['pages'][0]['extract'];
  $oceans = array("Pacific Ocean", "Atlantic Ocean", "Indian Ocean", "Southern Ocean", "Arctic Ocean");
  $largest_ocean = "";
  $largest_volume = 0;
  $largest_surface = 0;

  foreach ($oceans as $ocean) {
    preg_match_all('/'.preg_quote($ocean).'(.*)/i', $extract, $matches);
    $volume_matches = array();
    $surface_matches = array();

    foreach ($matches[0] as $match) {
      if (preg_match('/\d+(\.\d+)?\s*million\s*cubic\s*kilometers/i', $match, $volume_match)) {
        $volume_matches[] = $volume_match[0];
      }
      if (preg_match('/\d+(\.\d+)?\s*million\s*square\s*kilometers/i', $match, $surface_match)) {
        $surface_matches[] = $surface_match[0];
      }
    }

    if (count($volume_matches) > 0 && count($surface_matches) > 0) {
      $volume = str_replace(array(',', 'million', 'cubic', 'kilometers'), '', $volume_matches[0]) * 1000000;
      $surface = str_replace(array(',', 'million', 'square', 'kilometers'), '', $surface_matches[0]) * 1000000;
      if ($volume > $largest_volume && $surface > $largest_surface) {
        $largest_volume = $volume;
        $largest_surface = $surface;
        $largest_ocean = $ocean;
      }
    }
  }

  echo "The largest ocean on Earth in terms of both volume and surface area is the $largest_ocean with a volume of " . number_format($largest_volume) . " cubic kilometers and a surface area of " . number_format($largest_surface) . " square kilometers.";
}
?>

